-- Add complete Japanese Scarlet & Violet card sets SV7, SV7a and SV8.
-- Additive and idempotent: preserve existing rows and collection IDs; add missing cards, fill only missing images and add checklist variants only when none exist.

  series_name,set_name,set_code,language,release_date,advertised_card_count,
  checklist_source_url,checklist_scope_note,is_public
)
values
  ('Scarlet & Violet','Super Electric Breaker','SV8','JP',date '2024-10-18',138,'https://api.tcgdex.net/v2/ja/sets/sv8','138 numbered cards: 106 main-set cards and 32 secret cards. Japanese names and card details from TCGdex; scans from TCG Collector.',true),
  ('Scarlet & Violet','Stellar Miracle','SV7','JP',date '2024-07-19',135,'https://api.tcgdex.net/v2/ja/sets/sv7','135 numbered cards: 102 main-set cards and 33 secret cards. Japanese names and card details from TCGdex; scans from TCG Collector.',true),
  ('Scarlet & Violet','Paradise Dragona','SV7a','JP',date '2024-09-13',94,'https://api.tcgdex.net/v2/ja/sets/sv7a','94 numbered cards: 64 main-set cards and 30 secret cards. Japanese names and card details from TCGdex; scans from TCG Collector.',true)
on conflict (set_name,language) do nothing;

create temporary table pv_jp_sv7_sv7a_sv8_import (
 set_code text not null,local_id integer not null,collector_number text not null,card_name text not null,
 card_type text,rarity_label text,element_types text[] not null,guide_order integer not null,checklist_group text not null,image_url text not null
);

select s.id,d.collector_number,d.card_name,d.card_type,d.rarity_label,d.element_types,d.guide_order,d.image_url,
 case d.set_code when 'SV8' then 'https://www.tcgcollector.com/sets/11638/super-electric-breaker' when 'SV7' then 'https://www.tcgcollector.com/sets/11629/stellar-miracle' else 'https://www.tcgcollector.com/sets/11635/paradise-dragona' end,
 'https://api.tcgdex.net/v2/ja/cards/'||lower(d.set_code)||'-'||lpad(d.local_id::text,3,'0')
from pv_jp_sv7_sv7a_sv8_import d join public.card_sets s on s.language='JP' and s.set_code=d.set_code
where not exists(select 1 from public.cards c where c.card_set_id=s.id and c.collector_number=d.collector_number)
on conflict(card_set_id,collector_number) do nothing;

update public.cards c set image_url=d.image_url,
 image_source_url=coalesce(c.image_source_url,case d.set_code when 'SV8' then 'https://www.tcgcollector.com/sets/11638/super-electric-breaker' when 'SV7' then 'https://www.tcgcollector.com/sets/11629/stellar-miracle' else 'https://www.tcgcollector.com/sets/11635/paradise-dragona' end),
 source_url=coalesce(c.source_url,'https://api.tcgdex.net/v2/ja/cards/'||lower(d.set_code)||'-'||lpad(d.local_id::text,3,'0'))
from pv_jp_sv7_sv7a_sv8_import d join public.card_sets s on s.language='JP' and s.set_code=d.set_code
where c.card_set_id=s.id and c.collector_number=d.collector_number and c.image_url is null;

select c.id,'normal','Normale','normal',d.checklist_group,true
from public.cards c join public.card_sets s on s.id=c.card_set_id join pv_jp_sv7_sv7a_sv8_import d on d.set_code=s.set_code and d.collector_number=c.collector_number
where s.language='JP' and s.set_code in ('SV7','SV7a','SV8')
 and not exists(select 1 from public.card_print_variants v where v.card_id=c.id)
on conflict(card_id,variant_key) do nothing;

drop table pv_jp_sv7_sv7a_sv8_import;
